ValidationRule.errorConditionFormula:
AND( NOT($Setup.PMC_ProcessSwitches__c.PMC_BypassValidationRule__c) , OR(
AND( ISPICKVAL( Status , 'Pending with Customer'), NOT(ISPICKVAL( PMC_SS_ApprovalStatus__c , 'Approved')) ),
AND( ISCHANGED( Status ), ISPICKVAL(PRIORVALUE(Status),'Pending with Customer'), OR( ISPICKVAL( Status , 'Draft'), ISPICKVAL( Status , 'Archived') ) )
)
)
